+		delegate.setTreatment('config.foo', 'bare');
+		delegate.setTreatment('/vscode/config.foo', 'scoped');
+
+		expect(service.getTreatmentVariable<string>('config.foo')).toBe('bare');
+
+		service.dispose();
+	});
